"use strict";
globalThis.R = "";
globalThis.L = function(x) {
  R += x + ";";
};
globalThis.tick = function(n, label) {
  var p = Promise.resolve();
  for (var i = 0;i < n; i++)
    p = p.then(function() {});
  return p.then(function() {
    L(label);
  });
};
globalThis.thenable = function(v, label) {
  return { then: function(res) {
    L("then:" + label);
    res(v);
  } };
};
globalThis.ok = function(v) {
  L("v:" + JSON.stringify(v));
};
globalThis.bad = function(e) {
  L("e:" + (e && e.name) + (e && e.name === "Error" ? ":" + e.message : ""));
};
